    public static IReadOnlyCollection<TurkeySuperLigClubData> AllClubs => Clubs.Values.ToArray();

    public static TurkeySuperLigClubData GetClub(ClubId clubId) =>
        Clubs.TryGetValue(clubId.Value, out var club)
            ? club
            : throw new ArgumentOutOfRangeException(nameof(clubId), clubId.Value, "Club is not in the 2026-27 Süper Lig data pack.");

    public static bool TryGetClub(ClubId clubId, out TurkeySuperLigClubData club) =>
        Clubs.TryGetValue(clubId.Value, out club!);
}

public sealed record TurkeySuperLigClubData(
    long ClubId,
    string OfficialName,
    string RosterVerifiedOn,
    string RosterSourceUrl,
    string BrandingSourceUrl,
    string CrestResourcePath,
    string HomeKitResourcePath,
    string AwayKitResourcePath,
    string ThirdKitResourcePath,
    IReadOnlyList<MvpSquadPlayerProfile> Players)
{
    public IReadOnlyList<string> PlayerNames => Players.Select(player => player.DisplayName).ToArray();
}
